UPDATE companies SET description='Tri-Mack Plastics Manufacturing Corporation was founded in 1974 in Bristol, Rhode Island. The company began as a supplier of precision thermoplastic components to the aerospace industry.

The company provides vertically integrated manufacturing services including thermoplastic composites processing, injection molding, CNC machining, engineering support, and material selection. Its capabilities span from concept through production, with in-house quality inspection using CMMs, ultrasonic NDT, and in-machine probing on CNC milling centers.

Tri-Mack serves aerospace, defense, industrial, and medical markets. Aerospace OEMs such as GE Aerospace have recognized the company with Best in Class and Supplier Quality Awareness awards. Defense customers rely on the firm for precision components meeting complex regulatory standards. Industrial clients use materials like Victrex PEEK, Torlon PAI, Ultem PEI, and Ryton PPS for equipment assemblies. Medical equipment manufacturers depend on Tri-Mack for components that ensure accuracy and meet rigorous regulatory requirements.

The company differentiates itself through a quality management system certified to AS9100, ISO 9001, and NADCAP, which governs lot traceability, material certifications, and approved vendor requirements. On-staff designated supplier quality representatives (DSQRs) enable direct ship-to-stock for many customers. Vertically integrated capabilities and engineering collaboration aim to optimize parts for manufacturability from concept through delivery.', certifications=ARRAY['AS9100','ISO 9001','NADCAP','ITAR']::text[], profile='{"capabilities": ["Thermoplastic composites processing", "Injection molding", "CNC machining", "Engineering design for manufacturability", "Material selection assistance", "CMM dimensional inspection", "Ultrasonic non-destructive testing (NDT)", "In-machine probing", "New part introduction", "Lot traceability", "Material certification management", "Approved vendor management", "Direct ship-to-stock (DSQR)"], "industries": ["Aerospace", "Defense", "Industrial", "Medical"], "materials": ["Victrex PEEK", "Torlon PAI", "Ultem PEI", "Ryton PPS", "Thermoplastic composites"], "equipment": ["CMMs (coordinate measuring machines)", "Olympus ultrasonic tester", "CNC milling centers with in-machine probing"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["AS9100, ISO 9001, and NADCAP certified quality system", "On-staff DSQRs for direct ship-to-stock", "Vertically integrated manufacturing (thermoplastic composites, injection molding, machining)", "Engineering collaboration for manufacturability optimization", "Material expertise with high-performance thermoplastics (PEEK, PAI, PEI, PPS)"], "facts_used": ["Founded 1974 -> db", "Headquarters Bristol, Rhode Island -> db", "Certifications AS9100, ISO 9001, NADCAP, ITAR -> db", "Capabilities: thermoplastic composites processing, injection molding, machining -> /", "Engineering design for manufacturability -> /", "Material selection assistance -> /", "Industries: aerospace, defense, industrial, medical -> /", "Customer GE Aerospace with Best in Class and Supplier Quality Awareness awards -> /", "Materials: Victrex PEEK, Torlon PAI, Ultem PEI, Ryton PPS -> /", "Equipment: CMMs, Olympus ultrasonic tester, CNC milling centers -> /quality", "DSQR direct ship-to-stock -> /quality", "Lot traceability, material certifications, approved vendor requirements -> /quality", "In-machine probing on CNC milling centers -> /quality", "Quality system certified to AS9100/ISO 9001/NADCAP -> /quality"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "Tri-Mack''s vertically integrated manufacturing capabilities include thermoplastic composites processing, injection molding, machining and more.", "founded_year": "1974", "employee_count": "", "cage_code": "", "min_order": "", "export_compliance": ["ITAR registered"], "languages": [], "social_links": [], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='tri-mack-plastics-manufacturing-corporation' AND approved AND profile IS NULL;
UPDATE companies SET description='Tristate Electronic Manufacturing was founded in 1985 by Ryan Null in Boonsboro, Maryland. Null, a graduate of the Arundel Institute of Technology, began the business in his home basement before moving to a facility on Old National Pike. In 1990 the company relocated to its current site in the Washington County Business Park near Hagerstown, positioning it within 70 minutes of two major airports and at the intersection of I‑70 and I‑81.

The company provides electronic manufacturing services (EMS) for original equipment manufacturers, offering high‑speed surface‑mount and through‑hole circuit board assembly at low, medium, and high volumes. Capabilities include micro‑BGA placement down to 0.2 mm pitch, QFN/QFP/01005 component handling, pin‑and‑paste, automated paste and epoxy dispensing, turnkey and consigned‑kit supply‑chain management, new‑product‑introduction prototyping through production, box‑build and mechanical assembly, functional and environmental testing, HiPOT, IC programming, X‑ray inspection, automated optical inspection, conformal coating, and flying‑probe testing via third‑party partners. The facility operates under ESD controls per ANSI/ESD 20.20.

Tristate serves OEMs in health/medical, aerospace/defense, industrial/instrumentation, RF/microwave, communications, aviation, commercial, and government sectors. Its customer base spans technology firms that require ITAR‑registered, DFARS‑compliant manufacturing with ISO 9001:2015 and ISO 13485:2016 quality systems.

The company emphasizes agile, lean operations that enable quick reaction and customized solutions; a workforce with an average tenure of 14 years that brings deep experience across technology cycles; a culture of integrity and straightforward communication; and a strategic location that simplifies regional logistics. Ongoing investment in workforce development keeps the team current with ISO, IPC, and industry standards.', certifications=ARRAY['ISO 9001:2015','ISO 13485:2016','ITAR registered','DFARS 252.204.7012 (NIST 800-171, CMMC 2.0 Level 2)','IPC-A-610F Certified Instructor and Specialists','J-STD-001 Certified Instructor and Specialists','ESD per ANSI/ESD 20.20']::text[], profile='{"capabilities": ["High Speed Surface Mount Assembly", "Through-hole Circuit Board Assembly", "Micro BGA Assembly (0.2 mm pitch)", "QFN/QFP Assembly", "01005 Component Placement", "Pin and Paste Assembly", "Auto Dispensing of Paste and Epoxy", "Turnkey Manufacturing", "Consigned Kit Assembly", "New Product Introduction (NPI) Prototype & Production Manufacturing", "Box Build / Final / Mechanical Assembly & Test", "Functional Testing", "Environmental Testing", "HiPOT Testing", "IC Programming", "X-Ray Inspection", "Conformal Coating", "Automated Optical Inspection (AOI)", "100% Quality Assurance Inspection", "ESD Control per ANSI/ESD 20.20", "Supply Chain Management", "Product Improvement and Development with 3rd-party Partners", "Flying Probe Testing with 3rd-party Partners"], "industries": ["Health/Medical", "Aerospace/Defense", "Industrial/Instrumentation", "RF/Microwave", "Communications", "Aviation", "Commercial", "Government"], "materials": [], "equipment": ["ISM Ultraflex 3600 units", "Auto Incoming Receiving station from Juki/Essegi Automation", "Nordson Assure X-ray Component Inspection System"], "volume": "Low, Medium & High Volumes; Prototype to production", "lead_time": "", "tolerances": "", "built_on": ["Agile Solutions \u2013 small, lean, efficient business that reacts qu