UPDATE companies SET description='Two In One Manufacturing, Inc. operates from Nashua, New Hampshire, where it was founded in 1989 as a wire harness assembly business. The company is woman- and minority-owned, located in a HUBZone with small disadvantaged business status.

As a sub-contract manufacturer, the firm provides engineering and manufacturing assembly services across two divisions: General Assembly, Precision Assembly, Military Class Production, and Cables Production. It employs approximately 75 full-time manufacturing workers in a facility that includes 35,000 square feet of production space, 4,500 square feet of storage, and 1,700 square feet of office and cafeteria area. The operation handles high-mix, low-to-high volume work with lead times ranging from one day to four weeks, supported by a flexible supply chain and kanban capabilities.

The customer base spans automotive, industrial renewable energy, military defense and homeland security, medical, aerospace, RF microwave assemblies, telecommunications, instrumentation, semiconductor, and industrial equipment sectors. Clients range from companies whose products are too complex for smaller contract manufacturers to those whose volumes fall below the thresholds of large overseas providers, as well as customers needing early-stage collaboration on new product development.

The company emphasizes continuous improvement and customer satisfaction, citing full transparency and open communication from quote through delivery. Its quality policy targets on-time delivery of quality products at competitive prices, with ISO 9001:2015, ITAR registration, IPC compliance, and RoHS compliance underpinning its processes.', certifications=ARRAY['ISO 9001:2015','ITAR Registered','IPC Compliant','RoHS Compliant','TUV Certified Products','UL Certified Products']::text[], profile='{"capabilities": ["Subcontract assembly", "General assembly", "Precision assembly", "Military class production", "Cable and wire harness assembly", "Engineering and manufacturing assembly services", "Design support", "Labor provision", "Order fulfillment", "High-mix low-to-high volume production", "Quick-turn manufacturing", "Kanban inventory management"], "industries": ["Automotive", "Industrial renewable energy", "Military defense and homeland security", "Medical", "Aerospace", "RF microwave assemblies", "Telecommunications", "Instrumentation", "Semiconductor", "Industrial equipment"], "materials": [], "equipment": [], "volume": "High mix, low to high volume", "lead_time": "1 day to 4 weeks", "tolerances": "", "built_on": ["Lead times from one day to four weeks", "Kanban-capable flexible supply chain", "Full transparency and open communication throughout the project lifecycle", "Woman- and minority-owned HUBZone small disadvantaged business", "ITAR registered with ISO 9001:2015 certification"], "facts_used": ["Founded 1989 -> db and /about", "Headquarters Nashua, New Hampshire -> db", "Woman and minority owned, HUBZone, small disadvantaged status -> /about", "75 full-time manufacturing employees -> /about", "Two divisions: General Assembly, Precision Assembly, Military Class Production, Cables Production -> /about", "Facility: 35,000 sq ft production, 4,500 sq ft storage, 1,700 sq ft office/cafeteria -> /about", "Industries served list -> /about", "Certifications: ISO 9001:20