UPDATE companies SET description='A.F. Johnson Millwork Co. has operated from West Des Moines, Iowa since its founding in 1932 by Swedish immigrant Adolph F. Johnson. The company remains family-owned, with Johnson''s son Richard "Dick" Johnson joining the business and passing the same exacting standard to subsequent generations. What began as a shop building out national chain stores across the Midwest grew into a dedicated architectural millwork facility.

The 25-person team — designers, engineers, CNC programmers, and master cabinetmakers — produces custom architectural millwork, casework, solid-surface fabrications, and upholstered seating. Work flows through a single West Des Moines plant equipped with CNC machining centers, Microvellum manufacturing software, and AutoCAD drafting, handling projects valued from $50,000 to seven figures. Services span concept development, detailed 3D renderings, fabrication, finishing, and nationwide installation.

Primary markets include retail, corporate, hospitality, healthcare, education, religious, and government sectors. The firm collaborates directly with architects, designers, and general contractors on commercial projects that represent roughly 95 percent of its workload, with select high-end residential commissions rounding out the portfolio.

The company cites its AWI Premium Quality Certification (held since 1989), nine decades of continuous operation, and the integration of advanced digital tools with traditional craftsmanship as its core differentiators. Every project carries a full one-year warranty per AWI specifications, backed by multiple in-process quality checkpoints.', certifications=ARRAY['AWI Premium Quality Certified']::text[], profile='{"capabilities": ["Architectural millwork", "Custom casework", "Solid surface fabrication", "Upholstery and soft seating", "CNC machining and cutting", "Microvellum design and manufacturing software", "AutoCAD technical drawings", "3D modeling and visualization", "Automated material optimization", "Design development and concept sketches", "Project planning and scheduling", "Fabrication and assembly", "Finishing and staining", "Installation and project management", "Quality control and AWI Premium Grade compliance", "Budget estimation", "Material selection guidance", "Store fixtures", "Architectural paneling", "Metal fabrication integration"], "industries": ["Retail", "Corporate", "Hospitality", "Healthcare", "Education", "Religious", "Government"], "materials": ["Domestic hardwoods", "Exotic hardwoods", "Veneers", "High-pressure laminates", "Specialty finishes", "Solid surface materials", "Sustainable certified wood", "Metal (structural integration)"], "equipment": ["CNC machining centers"], "volume": "Projects from $50,000 to seven figures", "lead_time": "", "tolerances": "", "built_on": ["AWI Premium Quality Certified since 1989", "90+ years of continuous family-owned operation", "Microvellum, AutoCAD, and CNC technology paired with master cabinetmaking", "Nationwide installation capability from a central Midwest location", "Full design-through-installation service with a one-year AWI warranty"], "facts_used": ["Founded 1932 by Adolph F. Johnson -> /about", "Family-owned, father and son -> /about", "West Des Moines, Iowa headquarters -> /", "25 skilled professionals -> /", "AWI Premium Quality Certified since 1989 -> /", "Services: architectural millwork, custom casework, solid surface, upholstery -> /", "Industries: retail, corporate, hospitality, healthcare, education, religious, government -> /", "Project range $50K to seven figures -> /", "CNC machining centers, Microvellum, AutoCAD -> /capabilities", "Materials: hardwoods, veneers, laminates, solid surface, sustainable wood, metal -> /capabilities", "Full design-through-installation with one-year AWI warranty -> /", "90+ years continuous operation -> /about", "Commercial millwork 95% of work -> /about", "Founded year 1932 from database -> db", "Employee count 25 from database -> db", "Headquarters city/state from database -> db"], "company_type": "Manufacturer", "makes_products": "yes", "type_evidence": "A.F. Johnson Millwork Company has delivered architectural millwork excellence for nine decades.", "founded_year": "1932", "employee_count": "25", "cage_code": "", "min_order": "", "export_compliance": [], "languages": [], "social_links": [], "ownership_tags": ["Family-owned"]}'::jsonb, updated_at=now() WHERE slug='a-f-johnson-millwork-co' AND approved AND profile IS NULL;
UPDATE companies SET description='AADCO Medical, Inc. was founded in 1985 and is headquartered in Randolph, Vermont. The company operates its design, engineering, manufacturing, and distribution facilities from Catamount Commercial Park in Randolph.

As an original equipment manufacturer, AADCO develops and produces medical imaging equipment and radiology protection products. Its product line includes the ErgoLite® radiation protection apron, Hercules® and MRI-Safe® overhead suspension systems, mobile barriers, mobile lighting, lead gloves, and protective eyewear. All products are manufactured at the company''s Vermont facility.

The company serves hospitals, radiology labs, and interventional radiologists across the United States and internationally through its affiliate AADCO Medical, Asia-Pacific, Ltd. in Hong Kong. Customers include professionals such as Dr. Douglas Coldwell, an interventional radiologist who has endorsed the ErgoLite® apron for reducing back strain during long procedures.

AADCO emphasizes a quality management system certified to ISO 13485:2016, along with UL, CE, and CB certifications. The company highlights its U.S.-based manufacturing, a dedicated team of long-term employees, and lean processes that it says allow faster, more affordable delivery than larger competitors. Warranties extend beyond industry standards, including a lifetime warranty on radiation protection aprons and a 10-year warranty on Hercules® suspension systems.', certifications=ARRAY['ISO 13485:2016','UL','CE','CB','FDA registered','SFDA registered','JMH registered']::text[], profile='{"capabilities": ["Design and engineering of medical imaging equipment", "Manufacturing of radiation protection apparel", "Assembly of MRI-safe overhead suspension systems", "Quality management per ISO 13485:2016", "Distribution and sales support", "Product development and testing"], "industries": ["Medical imaging", "Radiology", "Healthcare"], "materials": ["Vinyl", "Lead (0.5 mm Pb equivalent)", "Woven absorbent liner", "Non-magnetic materials"], "equipment": ["ErgoLite\u00ae radiation protection apron", "Hercules\u00ae Suspension Systems", "MRI-Safe\u00ae Overhead Suspension Systems", "RayShield\u00ae Adjust-A-Height Pivoting Over-Table Barrier", "RayShield\u00ae Dual Protector X-Ray Glasses", "RayShield\u00ae Frame Mounted Barriers", "AADCO Mobile Barriers", "AADCO Mobile Lighting"], "volume": "", "lead_time": "", "tolerances": "", "built_on": ["Manufactured in the USA at their Vermont facility", "ISO 13485:2016 quality management system", "Lifetime warranty on radiation protection aprons", "10-year warranty on Hercules\u00ae suspension systems", "Proprietary MRI-Safe\u00ae non-magnetic equipment"], "facts_used": ["Founded in 1985 -> /about", "Headquarters in Randolph, Vermont -> /about", "Manufacturing facility in Randolph, Vermont -> /", "ISO 13485:2016 certification -> /about", "UL, CE, CB certifications -> /about", "FDA, SFDA, JMH registrations -> /about", "Product trademarks